# Search for grade, grader tail, facts, first wrong step
for term in ["[grade]", "[grader tail]", "[facts]", "[first wrong step]"]:
    r = await CONTEXT.search(term)
    print(f"\n{term}:")
    if isinstance(r, dict) and 'items' in r:
        for item in r['items']:
            print(f"  offset={item['offset']}, snippet={item['snippet'][:200]}")
    else:
        print(f"  {r}")
